  headerName: 'Order Date',
  field: 'orderDate',
  sortable: true,
  minWidth: 100,
  maxWidth: 200,
  headerTooltip: 'Order Date',

  // Method 1: valueFormatter
  valueFormatter: (p: any) =&gt; p.value ? this.datePipe.transform(p.value, 'MM/dd/yyyy HH:mm') : '',

  // (or)
 // Method 2: valueGetter
  valueGetter: (params) =&gt; {
    if (!params || !params.data) return null;

    const { modifiedDate } = params.data || {}; // params.data motam lo modifieDate ane key vunte adi return avtundi

    if (modifiedDate) {
      return this.dateFormat(
        modifiedDate,
        this.date_time_format
      );
    }

    return null;
  }
}
