</code></pre> AG Grid SideBar_DeafultColDef_tooltipValueGetter <pre><code>tooltipShowDelay = 500;

defaultColDef = {
  resizable: true,
  sortable: true,
  filter: true,
  flex: 1,
  tooltipValueGetter: (params: any) =&gt; {
    const colDef: any = params.colDef;

    if (colDef?.valueFormatter &amp;&amp; typeof colDef.valueFormatter === 'function') {
      return colDef.valueFormatter(params);
    }

    if (colDef?.valueGetter &amp;&amp; typeof colDef.valueGetter === 'function') {
      return colDef.valueGetter(params);
    }

    return params.value;
  },
};

