ts.file<pre><code>import { Component } from '@angular/core';

@Component({
  selector: 'app-parent',
  templateUrl: './parent.component.html',
  styleUrls: ['./parent.component.css']
})
export class ParentComponent {
  cities = [
    { cityId: 101, cityName: 'Hyderabad' },
    { cityId: 102, cityName: 'VijayaWada' },
    { cityId: 103, cityName: 'Maharashtra' },
    { cityId: 104, cityName: 'Bengaluru' }
  ];

  skills: string[] = ['Angular', 'React', 'Vue', 'Node.js', 'Python'];

  formModel: any = {
    firstName: '',
    lastName: '',
    gender: '',
    dob: '',
    city: '',
    email: '',
    age: null,
    password: '',
    address: '',
    appointmentTime: '',
    cricket: false,
    football: false,
    carrom: false,
    skills: [],
    resume: null
  };

  fileName = '';

  onSubmit(form: any): void {
    if (form.valid) {
      console.log('Form Submitted:', this.formModel);
    } else {
      console.warn('Form Invalid');
    }
  }

  onFileChange(event: any): void {
    const file = event.target.files[0];
    if (file) {
      this.formModel.resume = file;
      this.fileName = file.name;
    }
  }

  onSelectAllSkills(event: any): void {
    if (event.target.checked) {
      this.formModel.skills = [...this.skills];
    } else {
      this.formModel.skills = [];
    }
  }
}
</code></pre> html<pre><code>&lt;div class="container-fluide mx-3 card p-3"&gt;
  &lt;form #formRef="ngForm" (ngSubmit)="onSubmit(formRef)"&gt;
    &lt;div class="row"&gt;

      &lt;!-- First Name --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;First Name&lt;/mat-label&gt;
          &lt;input matInput name="firstName" [(ngModel)]="formModel.firstName" required #firstName="ngModel"&gt;
          &lt;mat-error *ngIf="firstName.invalid &amp;&amp; firstName.touched"&gt;First Name is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Last Name --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Last Name&lt;/mat-label&gt;
          &lt;input matInput name="lastName" [(ngModel)]="formModel.lastName" required #lastName="ngModel"&gt;
          &lt;mat-error *ngIf="lastName.invalid &amp;&amp; lastName.touched"&gt;Last Name is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Gender --&gt;
      &lt;div class="col-3"&gt;
        &lt;label&gt;Gender:&lt;/label&gt;&lt;br&gt;
        &lt;mat-radio-group name="gender" [(ngModel)]="formModel.gender" required #gender="ngModel"&gt;
          &lt;mat-radio-button value="male"&gt;Male&lt;/mat-radio-button&gt;
          &lt;mat-radio-button value="female"&gt;Female&lt;/mat-radio-button&gt;
        &lt;/mat-radio-group&gt;
        &lt;mat-error *ngIf="gender.invalid &amp;&amp; gender.touched"&gt;Gender is required&lt;/mat-error&gt;
      &lt;/div&gt;

      &lt;!-- Date of Birth --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Date of Birth&lt;/mat-label&gt;
          &lt;input matInput [matDatepicker]="picker" name="dob" [(ngModel)]="formModel.dob" 
                                                required #dob="ngModel"&gt;
          &lt;mat-datepicker-toggle matIconSuffix [for]="picker"&gt;&lt;/mat-datepicker-toggle&gt;
          &lt;mat-datepicker #picker&gt;&lt;/mat-datepicker&gt;
          &lt;mat-error *ngIf="dob.invalid &amp;&amp; dob.touched"&gt;DOB is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- City Dropdown --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Select City&lt;/mat-label&gt;
          &lt;mat-select name="city" [(ngModel)]="formModel.city" required #city="ngModel"&gt;
            &lt;mat-option *ngFor="let c of cities" [value]="c.cityId"&gt;{{ c.cityName }}&lt;/mat-option&gt;
          &lt;/mat-select&gt;
          &lt;mat-error *ngIf="city.invalid &amp;&amp; city.touched"&gt;City is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Email --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Email&lt;/mat-label&gt;
          &lt;input matInput name="email" [(ngModel)]="formModel.email" required email #email="ngModel"&gt;
          &lt;mat-error *ngIf="email.errors?.['required'] &amp;&amp; email.touched"&gt;Email is required&lt;/mat-error&gt;
          &lt;mat-error *ngIf="email.errors?.['email'] &amp;&amp; email.touched"&gt;Invalid email&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Age --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Age&lt;/mat-label&gt;
          &lt;input matInput type="number" name="age" [(ngModel)]="formModel.age" required #age="ngModel"&gt;
          &lt;mat-error *ngIf="age.invalid &amp;&amp; age.touched"&gt;Age is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Password --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Password&lt;/mat-label&gt;
          &lt;input matInput type="password" name="password" [(ngModel)]="formModel.password" required 
                                                        #password="ngModel"&gt;
          &lt;mat-error *ngIf="password.invalid &amp;&amp; password.touched"&gt;Password is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Address (Textarea) --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Address&lt;/mat-label&gt;
          &lt;textarea matInput name="address" [(ngModel)]="formModel.address" required #address="ngModel"&gt;&lt;/textarea&gt;
          &lt;mat-error *ngIf="address.invalid &amp;&amp; address.touched"&gt;Address is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Time Input --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Appointment Time&lt;/mat-label&gt;
          &lt;input matInput type="time" name="appointmentTime" [(ngModel)]="formModel.appointmentTime" 
                                                required #appointmentTime="ngModel"&gt;
          &lt;mat-error *ngIf="appointmentTime.invalid &amp;&amp; appointmentTime.touched"&gt;Time is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Hobbies (Checkboxes) --&gt;
