  resumeFileName?: string;
}

@Component({
  selector: 'app-parent',
  imports: [Child,MatDatepickerModule,CommonModule,MatTimepickerModule,MatFormFieldModule,MatInputModule,MatRadioModule,MatCheckboxModule,ReactiveFormsModule,MatSelectModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
