    public gender: string,
  ) {}
}


// STEP 2: ACTIONS (erdashboard.action.ts)
import { PatientInformation } from "@core/models/patient-registration/patient-information";

export class storePatientIdVisitIdAction {
  static readonly type = '[patientIdvisitId] PatientIdvisitId';

  constructor(public payload: {
    patientId: number,
    visitId: any,
    gender: string,
    patientModel: PatientInformation
  }) {}
}

export class clearPatientIdVisitIdAction {
  static readonly type = '[clearpatientIdvisitId] ClearPatientIdvisitId';

  constructor(public payload: {}) {}
}


// STEP 3: STATE (erdashboard.state.ts)
import { Injectable } from '@angular/core';
import { State, Action, StateContext, Selector } from '@ngxs/store';
import {
  clearPatientIdVisitIdAction,
  storePatientIdVisitIdAction
} from './erdashboard.action';

export class storePatientIdVisitIdModel {
  patientId: any;
  visitId: any;
  gender: string;
  patientModel: PatientInformation;
}

@State&lt;storePatientIdVisitIdModel&gt;({
  name: 'patientIdVisitId',
  defaults: {
    patientId: 0,
    visitId: 0,
    gender: '',
    patientModel: null,
  }
})
@Injectable()
export class storePatientIdVisitIdState {

  @Selector()
  static getPatientIdVisitId(state: storePatientIdVisitIdModel) {
    return state;
  }

  @Action(storePatientIdVisitIdAction)
  storePatientIdVisitIdAction(
    { patchState }: StateContext&lt;storePatientIdVisitIdModel&gt;,
    { payload }: storePatientIdVisitIdAction
  ) {
    const { patientModel } = payload || {};

    if (patientModel) {
      patientModel.patientType =
        patientModel.patientType ?? patientModel.patientVisitType;
    }

    patchState({
      patientId: payload.patientId,
      visitId: payload.visitId,
      gender: payload.gender,
      patientModel: patientModel,
    });
  }

  @Action(clearPatientIdVisitIdAction)
  clearPatientIdVisitIdAction(
    { patchState }: StateContext&lt;storePatientIdVisitIdModel&gt;
  ) {
    patchState({
      patientId: 0,
      visitId: 0,
      gender: '',
      patientModel: null,
    });
  }
}


// STEP 4: COMPONENT (Select &amp; Subscribe)
