  this.patientIdVisitId$
    .subscribe(res =&gt; {
      if (res) {
        this.patientId = res?.patientId;
        this.visitId = res?.visitId;
        this.patientName =
          res?.patientModel?.firstName + ' ' + res?.patientModel?.lastName;
