// check ssn duplicate check
     ssnDuplicateCheck(): AsyncValidatorFn {
      return (control: AbstractControl): Observable&lt;ValidationErrors | null&gt; =&gt; {
       if (!control.dirty ||!control.value || control.value === '999-99-9999') {
          return of(null);
        }
        if (control.value) {
          return this.patientRegistartionService.checkPatientSSN(control.value, 'SSN').pipe(
            map((response: any) =&gt; {
              const [{ status }] = response.body;
              if (status) {
                control.markAsTouched();
                return { ssnDuplicate: true };
              } else {
                return null; 
              }
            }),
            catchError((error) =&gt; {
              return of(null);
            })
          );
        }
      };
    }

